// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _check(address depositor, uint256 initAmt, uint256 addAmt) internal {
        initAmt = bound(initAmt, 0, 1000000000000000000000000000000);
        addAmt = bound(addAmt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(initAmt + addAmt >= initAmt);
        vm.assume(address(this).balance >= initAmt + addAmt);
        try c.Deposit{value: initAmt}() {} catch { return; }
        uint256 balAfterFirst;
        try c.balances(address(this)) returns (uint256 __r) { balAfterFirst = __r; } catch { return; }
        try c.Deposit{value: addAmt}() {} catch { return; }
        uint256 balAfterSecond;
        try c.balances(address(this)) returns (uint256 __r) { balAfterSecond = __r; } catch { return; }
        assertTrue(balAfterSecond >= balAfterFirst + addAmt);
    }

    function testFuzz_check(address depositor, uint256 initAmt, uint256 addAmt) public {
        _check(depositor, initAmt, addAmt);
    }

    receive() external payable {}
}
